#!/usr/bin/env python3
from pathlib import Path

ROOT = Path.cwd()
FRONTEND = ROOT / 'frontend'
if not FRONTEND.exists():
    raise SystemExit('找不到 frontend 目錄，請在 repo 根目錄執行。')
COMP = FRONTEND / 'components'
APP = FRONTEND / 'app'
COMP.mkdir(parents=True, exist_ok=True)

def write(path: Path, content: str):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        bak = path.with_suffix(path.suffix + '.bak_v86')
        if not bak.exists():
            bak.write_text(path.read_text(encoding='utf-8'), encoding='utf-8')
    path.write_text(content.strip() + '\n', encoding='utf-8')
    print('✅ wrote', path.relative_to(ROOT))

UTILS = r'''
export const num=(v:any,d=0)=>{const x=Number(v);return Number.isFinite(x)?x:d};
export const str=(v:any,d='')=>v===null||v===undefined?d:String(v);
export const fmt=(v:any,d=0)=>{const x=Number(v);return Number.isFinite(x)?x.toLocaleString('zh-TW',{maximumFractionDigits:d,minimumFractionDigits:d}):'-'};
export const fm=(v:any,d=0)=>{const x=Number(v);return Number.isFinite(x)?x.toLocaleString('zh-TW',{maximumFractionDigits:d}):'-'};
export const pct=(v:any,d=2)=>{const x=Number(v);return Number.isFinite(x)?`${x>0?'+':''}${x.toFixed(d)}%`:'-'};
export const tone=(v:any)=>{const x=Number(v);return !Number.isFinite(x)||x===0?'flat':x>0?'red':'green'};
export const toneCls=(v:any)=>`v86-${tone(v)}`;
export const code=(r:any)=>str(r?.stock_code||r?.code||r?.symbol||r?.etf_code);
export const name=(r:any)=>str(r?.stock_name||r?.name||r?.title||r?.etf_name);
export const ecode=(r:any)=>str(r?.etf_code||r?.code||r?.stock_code);
export const ename=(r:any)=>str(r?.etf_name||r?.name||r?.stock_name);
export const price=(r:any)=>r?.price??r?.close_price??r?.close??r?.last_price??r?.stock_price??r?.etf_price;
export const cpct=(r:any)=>r?.change_pct??r?.changePct??r?.pct??r?.pct_chg??r?.return_pct??r?.day_return;
export const mvb=(r:any)=>{const x=Number(r?.market_value_billion??r?.value_billion??r?.holding_value_billion??r?.amount_billion??r?.aum_billion);if(Number.isFinite(x))return x;const y=Number(r?.market_value??r?.holding_value??r?.amount);return Number.isFinite(y)?y/100000000:NaN};
export const lots=(r:any)=>{const x=Number(r?.shares_lots??r?.lots??r?.holding_lots);if(Number.isFinite(x))return x;const y=Number(r?.shares??r?.holding_shares);return Number.isFinite(y)?y/1000:NaN};
export const region=(r:any)=>{const c=ecode(r); if(c==='00986A'||c==='00998A')return '全球'; return r?.region||r?.investment_region||r?.investmentRegion||r?.area||r?.market_region||'-'};
export const ddate=(d:any)=>d?.data_date||d?.latest_date||d?.latestDate||d?.date||d?.updated_date||'';
export const chartRows=(d:any,fb:any[]=[])=>{const a=d?.price_history||d?.priceHistory||d?.chart||d?.history||d?.priceRows||d?.price_rows||fb;return Array.isArray(a)?a.map((r:any,i:number)=>({date:str(r.trade_date||r.date||r.data_date||r.updated_at||i),value:num(r.close_price??r.price??r.close??r.total_shares??r.shares_lots??r.weight??r.value,NaN)})).filter((x:any)=>Number.isFinite(x.value)).slice(-120):[]};
export function fav(code:string,name:string,type:'etf'|'stock'){if(typeof window==='undefined')return;const k='active_etf_favorites_v86';const a=JSON.parse(localStorage.getItem(k)||'[]');const ex=a.some((x:any)=>x.code===code&&x.type===type);localStorage.setItem(k,JSON.stringify((ex?a.filter((x:any)=>!(x.code===code&&x.type===type)):[{code,name,type,ts:Date.now()},...a]).slice(0,100)));}
'''
write(COMP/'mobileV86Utils.ts', UTILS)

SIGNALS = r'''
'use client';
import Link from 'next/link';
import {useMemo,useState} from 'react';
import {code,name,fmt,fm,pct,toneCls,cpct,price,num,ddate} from './mobileV86Utils';
type S='新增'|'刪除'|'加碼'|'減碼';
const flow=(r:any)=>{const x=Number(r?.amount_billion??r?.flow_billion??r?.capital_flow_billion??r?.delta_amount_billion??r?.money_billion);if(Number.isFinite(x))return x;const y=Number(r?.amount??r?.flow_amount??r?.delta_amount??r?.market_value_change);if(Number.isFinite(y))return y/100000000;return num(r?.delta_shares??r?.shares_change??r?.change_lots,0)*num(price(r),0)*1000/100000000};
const addc=(r:any)=>num(r?.buy_etf_count??r?.add_etf_count??r?.etf_add_count??r?.positive_etf_count??r?.buy_count??r?.add_count,0);
const redc=(r:any)=>num(r?.sell_etf_count??r?.reduce_etf_count??r?.etf_reduce_count??r?.negative_etf_count??r?.sell_count??r?.reduce_count,0);
const st=(r:any):S=>{const s=String(r?.status||r?.action||r?.change_type||'');if(s.includes('新增'))return'新增';if(s.includes('刪'))return'刪除';if(s.includes('減'))return'減碼';if(s.includes('加'))return'加碼';const d=num(r?.delta_shares??r?.shares_change??r?.change_lots,0);return d<0?'減碼':d>0?'加碼':'加碼'};
function Focus({title,item,kind}:any){if(!item)return null;const c=code(item),p=cpct(item),f=flow(item);return <Link href={`/stock/${c}?from=signals`} className={`v86-focus ${kind}`}><b>{title}</b><div className="v86-focus-grid2"><div><h3>{name(item)} <span>{c}</span></h3><strong className={toneCls(p)}>{fm(price(item),1)} <small>{pct(p,2)}</small></strong></div><div><em>資金動向</em><i className={f>=0?'v86-red':'v86-green'}>{f>=0?'+':''}{fmt(f,1)} 億</i><em>多空共識</em><i>{addc(item)}:{redc(item)}</i></div></div></Link>}
export default function SignalsClient(props:any){const data=props?.data||props;const rows:any[]=data?.rows||data?.items||data?.signals||[];const[range,setRange]=useState(String(data?.range_days||data?.signalRangeDays||data?.days||1));const[sel,setSel]=useState<S[]>(['新增','刪除','加碼','減碼']);const m=useMemo(()=>{const by=[...rows].sort((a,b)=>flow(b)-flow(a));const sum:any={新增:0,刪除:0,加碼:0,減碼:0};rows.forEach(r=>sum[st(r)]++);return{inflow:by.find(x=>flow(x)>0)||by[0],outflow:[...rows].sort((a,b)=>flow(a)-flow(b)).find(x=>flow(x)<0)||rows[0],mostAdd:[...rows].sort((a,b)=>addc(b)-addc(a)||flow(b)-flow(a))[0],mostReduce:[...rows].sort((a,b)=>redc(b)-redc(a)||flow(a)-flow(b))[0],sum}},[rows]);const shown=rows.filter(r=>sel.includes(st(r)));const fetched=data?.fetched_etf_count??data?.fetchedEtfCount??0,total=data?.total_etf_count??data?.totalEtfCount??fetched;const miss=data?.missing_etfs||data?.missingEtfs||[];return <main className="page v86-page"><section><div className="v86-label">訊號區間</div><div className="v86-seg">{[['1','今日'],['5','5日'],['10','10日'],['20','20日']].map(([v,t])=><button key={v} onClick={()=>setRange(v)} className={range===v?'on':''}>{t}</button>)}</div></section><section className="v86-title"><h1>{range==='1'?'今日':range+'日'}訊號</h1><p>已抓取 {fetched||total||0} / {total||fetched||0} 檔 ETF，資料日期 {ddate(data)||'-'}</p>{Array.isArray(miss)&&miss.length>0&&<mark>⚠️ {miss.length} 檔資料待補：{miss.slice(0,4).join('、')}</mark>}</section><section className="v86-focus-wrap"><Focus title="資金流入最多" item={m.inflow} kind="red"/><Focus title="資金流出最多" item={m.outflow} kind="green"/><Focus title="最多 ETF 加碼" item={m.mostAdd} kind="red"/><Focus title="最多 ETF 減碼" item={m.mostReduce} kind="green"/></section><h2 className="v86-h2">資金交易明細：共 {shown.length} 檔</h2><div className="v86-pills">{(['新增','刪除','加碼','減碼'] as S[]).map(x=><button key={x} onClick={()=>setSel(p=>p.includes(x)?p.filter(v=>v!==x):[...p,x])} className={`${sel.includes(x)?'on':''} ${x}`}>{x} <b>{m.sum[x]}</b></button>)}</div><section className="v86-list">{shown.slice(0,120).map((r,i)=>{const c=code(r),f=flow(r),p=cpct(r),x=st(r);return <Link href={`/stock/${c}?from=signals`} key={c+i} className="v86-row"><div><b>{name(r)}</b><span>{c}</span></div><div><b>{fm(price(r),1)}</b><span className={toneCls(p)}>{pct(p,2)}</span></div><em className={x}>{x}</em><strong className={f>=0?'v86-red':'v86-green'}>{f>=0?'+':''}{fmt(f,2)} 億</strong></Link>})}</section></main>}
'''
write(COMP/'SignalsClient.tsx', SIGNALS)

ETFLIST = r'''
'use client';
import Link from 'next/link';
import {useMemo,useState} from 'react';
import {ecode,ename,fm,pct,toneCls,price,cpct,num,region,ddate} from './mobileV86Utils';
type T='live'|'return'|'basic';
const amt=(r:any)=>{const x=Number(r?.amount_billion??r?.turnover_billion??r?.trading_amount_billion);if(Number.isFinite(x))return x;const y=Number(r?.amount??r?.turnover??r?.trading_amount);return Number.isFinite(y)?y/100000000:NaN};
const aum=(r:any)=>r?.aum_billion??r?.fund_size_billion??r?.asset_billion??r?.scale_billion;const r1w=(r:any)=>r?.one_week_return??r?.return_1w??r?.week_return;const tr=(r:any)=>r?.total_return??r?.since_inception_return??r?.return_since_inception??r?.ytd_return;const fee=(r:any)=>r?.expense_ratio??r?.fee??r?.management_fee??r?.total_fee;
function Card({r,tab}:any){const c=ecode(r),p=cpct(r);return <Link href={`/etf/${c}?from=etfs`} className="v86-card"><i className={p>=0?'red':'green'}/><div><div className="v86-card-top"><h3>{c}<span>{ename(r)}</span></h3><strong>{fm(price(r),2)}<small className={toneCls(p)}>{pct(p,2)}</small></strong></div>{tab==='live'&&<p><span>成交量 <b>{fm(r?.volume??r?.trade_volume)}</b></span><span>成交金額 <b>{fm(amt(r),1)} 億</b></span><span>更新 <b>{String(ddate(r)||r?.updated_at||'-').slice(5,16).replace('T',' ')}</b></span></p>}{tab==='return'&&<p><span>1週報酬 <b className={toneCls(r1w(r))}>{pct(r1w(r),1)}</b></span><span>成立以來 <b className={toneCls(tr(r))}>{pct(tr(r),1)}</b></span><span>配息 <b>{r?.dividend_frequency||'-'}</b></span></p>}{tab==='basic'&&<p><span>資產規模 <b>{fm(aum(r))} 億</b></span><span>費用 <b>{Number.isFinite(Number(fee(r)))?fm(fee(r),2)+'%':'-'}</b></span><span>區域 <b>{region(r)}</b></span></p>}<div className="v86-badges"><span>股價 {Number.isFinite(Number(price(r)))?'✓':'-'}</span><span>成分股 {(r?.has_holding_data||r?.latest_holding_date||r?.latestHoldingDate)?'✓':'-'}</span><span>歷史 {(r?.has_price_history||r?.history_ready)?'✓':'-'}</span></div></div></Link>}
export default function EtfListClient(props:any){const rows:any[]=props?.rows||props?.data?.rows||props?.data||props?.etfs||[];const[tab,setTab]=useState<T>('live');const[q,setQ]=useState('');const sorted=useMemo(()=>{const f=(Array.isArray(rows)?rows:[]).filter(r=>`${ecode(r)} ${ename(r)}`.toLowerCase().includes(q.trim().toLowerCase()));return[...f].sort((a,b)=>tab==='return'?num(tr(b),-999)-num(tr(a),-999):tab==='basic'?num(aum(b),-999)-num(aum(a),-999):num(cpct(b),-999)-num(cpct(a),-999))},[rows,tab,q]);return <main className="page v86-page"><section className="v86-head"><div><h1>ETF 列表</h1><p>共 {sorted.length} 檔，每檔 ETF 可點進詳情。</p></div><div className="v86-mini"><button onClick={()=>setTab('live')} className={tab==='live'?'on':''}>即時</button><button onClick={()=>setTab('return')} className={tab==='return'?'on':''}>報酬</button><button onClick={()=>setTab('basic')} className={tab==='basic'?'on':''}>基本</button></div></section><input className="v86-search" value={q} onChange={e=>setQ(e.target.value)} placeholder="搜尋 ETF 或代號"/><section>{sorted.map((r,i)=><Card r={r} tab={tab} key={ecode(r)+i}/>)}</section></main>}
'''
write(COMP/'EtfListClient.tsx', ETFLIST)

